#!/usr/bin/env bash
set -euo pipefail
shopt -s nullglob
mkdir -p img
for f in *.jpg; do mv -f "$f" "img/$f"; echo "movido: $f"; done
for n in aexxen-coletiva aexxen-evolucao aexxen-comunidade flex-agenda juvenil-treino loja-encordoamento professores-gesto-close; do test -f "img/$n.jpg" || { echo "ERRO: falta img/$n.jpg"; exit 1; }; done
echo '' | base64 -d > /tmp/preencher.py
python3 /tmp/preencher.py
git config user.name "preencher-slots"
git config user.email "actions@github.com"
git add -A
git commit -m "Preenche os 7 quadros vazios restantes (A-EXXEN, FLEX, Juvenil, Loja, Professores)"
git push
echo FIM
